const items = $input.all();
const processed = $getWorkflowStaticData('global');
if (!processed.videoIds) processed.videoIds = {};

const dayFormatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Sao_Paulo',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
});
const todaySP = dayFormatter.format(new Date());

const pending = [];
for (const item of items) {
  const link = item.json.link || item.json.guid || '';
  const match = link.match(/(?:v=|\/shorts\/|youtu\.be\/)([a-zA-Z0-9_-]{11})/);
  const videoId = match ? match[1] : null;
  if (!videoId) continue;
  if (processed.videoIds[videoId]) continue;

  const pubDateStr = item.json.pubDate || item.json.isoDate;
  if (!pubDateStr) continue;

  const pubDaySP = dayFormatter.format(new Date(pubDateStr));
  if (pubDaySP !== todaySP) continue;

  pending.push({
    videoId,
    title: item.json.title,
    link,
    pubDate: pubDateStr
  });
}

pending.sort((a, b) => new Date(a.pubDate) - new Date(b.pubDate));

return pending.map((video) => ({ json: video }));

const variants = [
  'Deixa o like e se inscreve no canal — estamos na meta dos 100 mil! ❤️',
  'Me ajuda a bater a meta de 100 mil inscritos? Se inscreve no canal ❤️',
  'Estamos rumo aos 100K! Se ainda nao e inscrito, se inscreve aqui ❤️',
  'Meta: 100 mil inscritos! Sua inscricao ajuda demais ❤️',
  'Quer me ajudar na meta de 100 mil? E so se inscrever no canal ❤️',
  'Faltam poucos pra meta de 100 mil inscritos — se inscreve no canal? ❤️',
  'Se curtiu, se inscreve no canal! Estamos indo pros 100 mil ❤️',
  'Me ajuda nessa meta de 100 mil inscritos se inscrevendo aqui ❤️',
  'Bora juntos aos 100 mil inscritos? Se inscreve no canal ❤️',
  'Obrigado por assistir! Me ajuda bater 100 mil inscritos se inscrevendo no canal ❤️',
];

const item = $input.first().json;
const commentText = variants[Math.floor(Math.random() * variants.length)];

return [{ json: { ...item, commentText } }];

const processed = $getWorkflowStaticData('global');
if (!processed.videoIds) processed.videoIds = {};

const item = $('Sortear comentario (10 variantes)').item.json;
const videoId = item.videoId;
const commentId = $json.id || 'unknown';

processed.videoIds[videoId] = {
  commentId,
  postedAt: new Date().toISOString(),
  source: 'rss-catchup'
};

return [{
  json: {
    videoId,
    commentId,
    title: item.title,
    studioUrl: `https://studio.youtube.com/video/${videoId}/comments`,
    message: 'Comentario postado. Fixe manualmente no YouTube Studio (pin nao existe na API).'
  }
}];

const delaySec = 45 + Math.floor(Math.random() * 46);
await new Promise((resolve) => setTimeout(resolve, delaySec * 1000));
return $input.all();
